//! QR encoder (IM22 barcodes, own implementation). Oracles are independent of the encoder:
//! the published Reed–Solomon vector of the "HELLO WORLD" 1-M example (ISO/IEC 18004 tutorial
//! data), the published format- and version-information tables, and complete module matrices
//! generated by Apple CoreImage (`tests/fixtures/qr-coreimage.txt`, tool in `research/qr-reference/`).

#![allow(clippy::unwrap_used, clippy::panic)]

use burnburn_generators::{
    GenError, QR_MAX_VERSION, QrEcc, QrParams, qr, qr_encode, qr_encode_with, qr_format_bits, qr_reed_solomon,
    qr_version_bits,
};

#[test]
fn reed_solomon_matches_the_published_hello_world_1m_vector() {
    // "HELLO WORLD", alphanumeric, 1-M: data codewords and their 10 error-correction codewords.
    let data = [32, 91, 11, 120, 209, 114, 220, 77, 67, 64, 236, 17, 236, 17, 236, 17];
    assert_eq!(qr_reed_solomon(&data, 10), vec![196, 35, 39, 119, 235, 215, 231, 226, 93, 23]);
}

#[test]
fn format_information_matches_the_published_table() {
    let table: [(QrEcc, [&str; 8]); 4] = [
        (
            QrEcc::L,
            [
                "111011111000100",
                "111001011110011",
                "111110110101010",
                "111100010011101",
                "110011000101111",
                "110001100011000",
                "110110001000001",
                "110100101110110",
            ],
        ),
        (
            QrEcc::M,
            [
                "101010000010010",
                "101000100100101",
                "101111001111100",
                "101101101001011",
                "100010111111001",
                "100000011001110",
                "100111110010111",
                "100101010100000",
            ],
        ),
        (
            QrEcc::Q,
            [
                "011010101011111",
                "011000001101000",
                "011111100110001",
                "011101000000110",
                "010010010110100",
                "010000110000011",
                "010111011011010",
                "010101111101101",
            ],
        ),
        (
            QrEcc::H,
            [
                "001011010001001",
                "001001110111110",
                "001110011100111",
                "001100111010000",
                "000011101100010",
                "000001001010101",
                "000110100001100",
                "000100000111011",
            ],
        ),
    ];
    for (ecc, masks) in table {
        for (mask, bits) in masks.iter().enumerate() {
            let want = u16::from_str_radix(bits, 2).unwrap();
            assert_eq!(qr_format_bits(ecc, mask as u8), want, "{ecc:?} mask {mask}");
        }
    }
}

#[test]
fn version_information_matches_the_published_table() {
    assert_eq!(qr_version_bits(6), None, "versions below 7 carry no version information");
    for (v, bits) in
        [(7, "000111110010010100"), (8, "001000010110111100"), (9, "001001101010011001"), (10, "001010010011010011")]
    {
        assert_eq!(qr_version_bits(v), Some(u32::from_str_radix(bits, 2).unwrap()), "version {v}");
    }
}

struct Reference {
    ecc: QrEcc,
    message: Vec<u8>,
    rows: Vec<Vec<bool>>,
}

fn references() -> Vec<Reference> {
    let text = include_str!("fixtures/qr-coreimage.txt");
    let mut out: Vec<Reference> = Vec::new();
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
        if let Some(rest) = line.strip_prefix("case ") {
            let (lvl, hex) = rest.split_once(' ').unwrap();
            let ecc = match lvl {
                "L" => QrEcc::L,
                "M" => QrEcc::M,
                "Q" => QrEcc::Q,
                "H" => QrEcc::H,
                other => panic!("level {other}"),
            };
            let message = (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect();
            out.push(Reference { ecc, message, rows: Vec::new() });
        } else {
            out.last_mut().unwrap().rows.push(line.chars().map(|c| c == '1').collect());
        }
    }
    out
}

/// The 15 format bits as placed next to the top-left finder (row 8 / column 8), MSB first.
fn format_bits_of(rows: &[Vec<bool>]) -> u16 {
    let mut cells: Vec<(usize, usize)> = (0..=5).map(|c| (8, c)).collect();
    cells.extend([(8, 7), (8, 8), (7, 8)]);
    cells.extend((0..=5).rev().map(|r| (r, 8)));
    cells.iter().fold(0u16, |acc, &(r, c)| (acc << 1) | u16::from(rows[r][c]))
}

#[test]
fn matrices_match_the_coreimage_reference_for_its_mask() {
    let refs = references();
    assert_eq!(refs.len(), 10);
    let mut versions = Vec::new();
    for r in &refs {
        let size = r.rows.len();
        let version = ((size - 17) / 4) as u8;
        let bits = format_bits_of(&r.rows);
        let mask = (0..8).find(|m| qr_format_bits(r.ecc, *m) == bits).expect("reference format bits are valid");
        let code = qr_encode_with(&r.message, r.ecc, None, Some(mask)).unwrap();
        assert_eq!((code.version(), code.size()), (version, size), "smallest version for {} bytes", r.message.len());
        for (row, cells) in r.rows.iter().enumerate() {
            let ours: Vec<bool> = (0..size).map(|c| code.is_dark(row, c)).collect();
            assert_eq!(&ours, cells, "{:?} v{version} mask {mask}: row {row} differs", r.ecc);
        }
        versions.push(version);
    }
    assert!(versions.contains(&1) && versions.contains(&7) && versions.contains(&10), "{versions:?}");
}

#[test]
fn automatic_mask_choice_agrees_with_the_reference_encoder() {
    for r in references() {
        let bits = format_bits_of(&r.rows);
        let theirs = (0..8).find(|m| qr_format_bits(r.ecc, *m) == bits).unwrap();
        let ours = qr_encode(&r.message, r.ecc).unwrap();
        assert_eq!(ours.mask(), theirs, "{:?} {} bytes", r.ecc, r.message.len());
    }
}

#[test]
fn longest_input_per_level_fits_version_10_and_one_more_byte_is_refused() {
    for (ecc, max) in [(QrEcc::L, 271), (QrEcc::M, 213), (QrEcc::Q, 151), (QrEcc::H, 119)] {
        let code = qr_encode(&vec![b'a'; max], ecc).unwrap();
        assert_eq!(code.version(), QR_MAX_VERSION);
        let err = qr_encode(&vec![b'a'; max + 1], ecc).unwrap_err();
        assert!(matches!(err, GenError::Count { param: "data", .. }), "{err:?}");
    }
    assert!(matches!(qr_encode(b"", QrEcc::M), Err(GenError::Count { .. })));
    assert!(matches!(qr_encode_with(b"x", QrEcc::M, Some(11), None), Err(GenError::Count { param: "version", .. })));
    assert!(matches!(qr_encode_with(b"x", QrEcc::M, None, Some(8)), Err(GenError::Count { param: "mask", .. })));
    // A forced version that is too small is refused, not silently enlarged.
    assert!(qr_encode_with(&[b'a'; 20], QrEcc::H, Some(1), None).is_err());
}

#[test]
fn qr_geometry_is_one_square_per_dark_module_inside_the_quiet_zone() {
    let p = QrParams { module: 0.5, quiet_modules: 4, min_module: 0.2 };
    let sym = qr(b"hello world", QrEcc::M, &p).unwrap();
    let n = sym.code.size();
    let dark = (0..n).flat_map(|r| (0..n).map(move |c| (r, c))).filter(|&(r, c)| sym.code.is_dark(r, c)).count();
    assert_eq!(sym.width, (n as f64 + 8.0) * 0.5);
    let area: f64 = sym.path.subpaths().iter().map(|s| s.signed_area().unwrap().abs()).sum();
    assert!((area - dark as f64 * 0.25).abs() < 1e-9, "{area} vs {}", dark as f64 * 0.25);
    let b = sym.path.bounds().unwrap();
    assert!(b.min().x >= 2.0 - 1e-12 && b.max().x <= sym.width - 2.0 + 1e-12);
    // Too small for the material: refused (E10, no silent clamping).
    let tiny = QrParams { module: 0.1, ..p };
    assert!(matches!(qr(b"x", QrEcc::M, &tiny), Err(GenError::TooSmall { .. })));
}
